<script setup lang="ts">
import {computed,ref,watch,nextTick,onBeforeUnmount,toRaw} from 'vue';
import {defaultCodeAppearance,normalizeCodeAppearance,codeRoles,type CodeRole,type CodePalette,type CodeAppearance} from '@shared/codeAppearance';
import {appearanceCss,codeRoleNames} from '../core/appearanceCss';
import {highlightSyntax,releaseSyntax} from '../core/syntaxClient';
import {renderSyntaxLine,renderTextLine} from '../core/highlight';
import type {SyntaxData} from '../core/syntaxTypes';
import ToolButton from '@/components/ui/ToolButton.vue';
const props=defineProps<{value:CodeAppearance}>();
const open=ref(false),mode=ref<'light'|'dark'>('light'),draft=ref(defaultCodeAppearance()),busy=ref(false),notice=ref(''),conflict=ref(false),dialog=ref<HTMLElement>(),trigger=ref<HTMLButtonElement>(),tokens=ref<SyntaxData>();
let baseline='',generation=0,parent:HTMLElement|undefined;
const palette=computed(()=>draft.value[mode.value]);
const colors:Record<'light'|'dark',Record<CodeRole,string>>={light:{foreground:'#20262e',background:'#ffffff',lineNumber:'#9aa6b8',keyword:'#0000ff',string:'#a31515',comment:'#008000',number:'#098658',function:'#795e26',type:'#267f99',property:'#001080',search:'#fde68a'},dark:{foreground:'#e8ecf2',background:'#242a32',lineNumber:'#8d9bae',keyword:'#569cd6',string:'#ce9178',comment:'#6a9955',number:'#b5cea8',function:'#dcdcaa',type:'#4ec9b0',property:'#9cdcfe',search:'#854d0e'}};
const tokenRoles=codeRoles.filter(role=>!['background','lineNumber','search'].includes(role));
const sample='/* 多行注释 / comment\n   code preview */\ninterface User { name: string; }\nconst count = 42;\nfunction greet(user: User) {\n  return `Hello ${user.name}`;\n}';
const previewHtml=computed(()=>sample.split('\n').map((line,i)=>`<div class="text-line"><span class="line-no">${i+1}</span><code class="line-body">${tokens.value?renderSyntaxLine(line,tokens.value.lines[i],tokens.value.styles,'return'):renderTextLine(line,'','return')}</code></div>`).join(''));
const validation=computed(()=>{try{return {css:appearanceCss(draft.value,'[data-code-preview]',true),error:''};}catch(error){return {css:appearanceCss({...draft.value,fontFamily:'',customCss:''},'[data-code-preview]',true),error:error instanceof Error?error.message:'CSS 格式无效。'};}});
const changed=computed(()=>JSON.stringify(normalizeCodeAppearance(draft.value))!==baseline);
async function show(){draft.value=normalizeCodeAppearance(props.value);baseline=JSON.stringify(draft.value);mode.value=document.documentElement.dataset.theme==='dark'?'dark':'light';notice.value='';conflict.value=false;open.value=true;const token=++generation;parent=trigger.value?.closest('.settings-panel') as HTMLElement|undefined;if(parent)parent.inert=true;await nextTick();dialog.value?.querySelector<HTMLButtonElement>('.appearance-close')?.focus();const data=await highlightSyntax('appearance-preview:sample',sample,'typescript');if(open.value&&generation===token)tokens.value=data;}
function close(){if(busy.value)return;generation++;open.value=false;releaseSyntax('appearance-preview');if(parent)parent.inert=false;parent=undefined;void nextTick(()=>trigger.value?.focus({preventScroll:true}));}
function reset(){draft.value=defaultCodeAppearance();notice.value='已恢复默认预览，点击“应用并保存”后生效。';}
function reload(){draft.value=normalizeCodeAppearance(props.value);baseline=JSON.stringify(draft.value);conflict.value=false;notice.value='已载入最新设置。';}
watch(()=>props.value,value=>{if(!open.value||busy.value)return;const next=JSON.stringify(normalizeCodeAppearance(value));if(next===baseline)return;if(!changed.value)reload();else conflict.value=true;},{deep:true});
function color(role:CodeRole,event:Event){palette.value.colors[role]=(event.target as HTMLInputElement).value;notice.value='';}
function flag(role:CodeRole,bit:number){palette.value.styles[role]=(palette.value.styles[role]??0)^bit;notice.value='';}
function preset(event:Event){const value=(event.target as HTMLSelectElement).value;if(value==='default')draft.value[mode.value]={colors:{},styles:{}};else{const next:CodePalette={colors:{...colors[mode.value]},styles:{}};if(value==='soft'){Object.assign(next.colors,mode.value==='light'?{keyword:'#7053a5',string:'#277b64',comment:'#667085',number:'#b45309'}:{keyword:'#c4a7e7',string:'#9ccfd8',comment:'#9aa5b5',number:'#f6c177'});}else Object.assign(next.colors,mode.value==='light'?{foreground:'#000000',background:'#ffffff',comment:'#005700',keyword:'#0000a0'}:{foreground:'#ffffff',background:'#000000',comment:'#88e188',keyword:'#82b7ff'});draft.value[mode.value]=next;}(event.target as HTMLSelectElement).value='';notice.value='';}
async function save(){if(validation.value.error||busy.value)return;busy.value=true;notice.value='';try{const settings=await window.localPreview.setSettings({codeAppearance:normalizeCodeAppearance(toRaw(draft.value))});draft.value=normalizeCodeAppearance(settings.codeAppearance);baseline=JSON.stringify(draft.value);conflict.value=false;notice.value='已应用并保存。';}catch{notice.value='保存失败，修改仍在此窗口中，请重试。';}finally{busy.value=false;}}
function keys(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();close();}else if(event.key==='Tab'){const list=Array.from(dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')||[]).filter(e=>e.getClientRects().length);const first=list[0],last=list.at(-1);if(!list.length){event.preventDefault();return;}if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}}
function cssExample(){draft.value.customCss='/* 白天与黑夜可分别设置；也可省略前缀 */\n.light .comment { color: #667085; font-style: italic; }\n.dark .comment { color: #9aa5b5; font-style: italic; }\n.keyword { font-weight: bold; }';}
onBeforeUnmount(()=>{generation++;releaseSyntax('appearance-preview');if(parent)parent.inert=false;});
</script>
<template>
  <div class="setting-row"><span>代码高亮外观</span><button ref="trigger" type="button" class="appearance-open" title="编辑高亮主题和自定义 CSS" @click="show">自定义…</button></div>
  <Teleport to="body">
    <div v-if="open" class="code-appearance-backdrop" @click.self="close" @keydown.stop="keys">
      <section ref="dialog" class="code-appearance-dialog" role="dialog" aria-modal="true" aria-labelledby="code-appearance-title" :aria-busy="busy">
        <header><h2 id="code-appearance-title">代码高亮外观</h2><ToolButton class="appearance-close" icon="cancel" title="关闭代码高亮外观" :disabled="busy" @click="close"/></header>
        <fieldset class="appearance-fields" :disabled="busy" aria-label="外观编辑区域">
          <div class="appearance-body">
          <div class="appearance-controls">
            <div class="appearance-mode" role="group" aria-label="编辑配色"><button type="button" :aria-pressed="mode==='light'" @click="mode='light'">白天</button><button type="button" :aria-pressed="mode==='dark'" @click="mode='dark'">黑夜</button><select aria-label="使用配色预设" :value="''" @change="preset"><option value="" disabled>配色预设</option><option value="default">语法默认</option><option value="soft">柔和配色</option><option value="contrast">高对比</option></select></div>
            <label class="appearance-font">代码字体<input v-model="draft.fontFamily" aria-label="代码字体" maxlength="100" placeholder="Consolas, Microsoft YaHei, monospace"/><span>留空使用默认字体，字体需已安装在本机。</span></label>
            <div class="appearance-color-list">
              <div v-for="role in codeRoles" :key="role" class="appearance-color-row" :data-code-role="role">
                <label :for="'appearance-color-'+role">{{codeRoleNames[role]}}</label><input :id="'appearance-color-'+role" type="color" :aria-label="codeRoleNames[role]+'颜色'" :value="palette.colors[role]||colors[mode][role]" @input="color(role,$event)"/><span class="appearance-value">{{palette.colors[role]||'语法默认'}}</span>
                <span v-if="tokenRoles.includes(role)" class="appearance-font-flags"><button v-for="(name,bit) in {1:'斜体',2:'粗体',4:'下划线'}" :key="bit" type="button" :title="codeRoleNames[role]+' '+name" :aria-label="codeRoleNames[role]+' '+name" :aria-pressed="!!((palette.styles[role]??0)&Number(bit))" @click="flag(role,Number(bit))"><i v-if="Number(bit)===1">I</i><b v-else-if="Number(bit)===2">B</b><u v-else>U</u></button></span><span v-else class="appearance-font-flags"></span>
                <ToolButton icon="reset" :title="'恢复'+codeRoleNames[role]+'默认样式'" :disabled="palette.colors[role]===undefined&&palette.styles[role]===undefined" @click="delete palette.colors[role];delete palette.styles[role]"/>
              </div>
            </div>
          </div>
          <div class="appearance-preview-column">
            <p class="appearance-caption">即时预览 · {{mode==='light'?'白天':'黑夜'}}（代码与 Markdown 代码块共用）</p>
            <component :is="'style'" v-text="validation.css"/>
            <div data-code-preview :data-code-mode="mode" class="appearance-sample"><div class="text-code" v-html="previewHtml"></div></div>
            <details class="appearance-css" open><summary>自定义 CSS</summary><div class="appearance-css-actions"><span>CSS 会覆盖上方主题设置。</span><button type="button" :disabled="!!draft.customCss" @click="cssExample">填入示例</button><button type="button" :disabled="!draft.customCss" @click="draft.customCss=''">清空 CSS</button></div><textarea v-model="draft.customCss" aria-label="自定义代码 CSS" spellcheck="false" maxlength="16384" placeholder=".comment { color: #667085; font-style: italic; }"/><p class="appearance-css-help">选择器：.code / .token / .keyword / .string / .comment / .number / .function / .type / .property / .line-number / .search-hit，可加 .light / .dark 前缀。支持颜色、字体、文字装饰、边框颜色和 tab-size；仅作用于代码区域。</p></details>
            <p v-if="validation.error" class="appearance-error" role="alert">{{validation.error}}</p>
          </div>
          </div>
        </fieldset>
        <footer><div class="appearance-status" role="status"><span v-if="conflict">其他窗口已修改外观，应用会使用当前编辑设置。<button type="button" :disabled="busy" @click="reload">载入最新</button></span><span v-else>{{notice||'预览不会修改正在阅读的文件；应用后所有窗口同步。'}}</span></div><div class="appearance-actions"><button type="button" class="appearance-reset" :disabled="busy" @click="reset">恢复默认</button><button type="button" class="appearance-cancel" :disabled="busy" @click="close">取消</button><button type="button" class="appearance-save" :disabled="busy||!!validation.error||!changed" @click="save">{{busy?'正在保存…':'应用并保存'}}</button></div></footer>
      </section>
    </div>
  </Teleport>
</template>
<style scoped>
.appearance-open{padding:6px 14px;border:1px solid var(--line);border-radius:5px;background:var(--well);color:var(--text)}
.code-appearance-backdrop{position:fixed;inset:0;z-index:60;display:grid;place-items:center;background:rgb(20 28 40 / 45%)}
.code-appearance-dialog{width:min(980px,94vw);max-height:92vh;display:flex;flex-direction:column;border:1px solid var(--line);border-radius:8px;background:var(--panel);color:var(--text);box-shadow:0 12px 40px rgb(0 0 0 / 18%);font-size:13px;overflow:hidden}
.code-appearance-dialog>header{display:flex;justify-content:space-between;align-items:center;padding:10px 16px;border-bottom:1px solid var(--line);flex-shrink:0}.code-appearance-dialog h2{font-size:15px;margin:0}
.appearance-fields{display:contents;border:0;margin:0;padding:0}.appearance-body{margin:0;min-width:0;display:grid;grid-template-columns:minmax(350px,.9fr) minmax(340px,1fr);gap:20px;overflow:auto;overscroll-behavior:contain;min-height:0;padding:16px}.appearance-controls,.appearance-preview-column{min-width:0}.appearance-mode{display:flex;gap:6px;align-items:center;margin-bottom:12px}.code-appearance-dialog button{cursor:pointer}.code-appearance-dialog button:disabled{cursor:default;opacity:.5}.appearance-mode button,.appearance-actions button,.appearance-css-actions button,.appearance-status button{padding:5px 10px;border:1px solid var(--line);border-radius:4px;color:var(--text);background:var(--well)}button[aria-pressed="true"]{color:var(--accent);border-color:var(--accent);background:var(--panel)}
.appearance-font{display:grid;gap:5px;margin-bottom:12px}.appearance-font input{width:100%;box-sizing:border-box;padding:6px;background:var(--well);color:var(--text);border:1px solid var(--line);border-radius:4px}.appearance-font span,.appearance-css-help,.appearance-caption,.appearance-css-actions{color:var(--muted);font-size:12px;line-height:1.5}.appearance-caption{margin:0 0 8px}
.appearance-color-row{display:grid;grid-template-columns:75px 30px minmax(58px,1fr) 77px 28px;align-items:center;gap:5px;border-top:1px solid var(--line);padding:5px 0}.appearance-color-row input[type="color"]{width:28px;height:26px;padding:0;border:0;background:transparent;cursor:pointer}.appearance-value{font-size:11px;color:var(--muted)}.appearance-font-flags{display:flex;gap:2px}.appearance-font-flags button{border:1px solid var(--line);border-radius:3px;background:var(--well);color:var(--text);width:24px;height:24px;padding:0}.appearance-font-flags button[aria-pressed="true"]{color:var(--accent);border-color:var(--accent)}
.appearance-sample{overflow:auto;border:1px solid var(--line);border-radius:5px;margin-bottom:14px;background:var(--panel)}.appearance-sample :deep(.text-code){font-size:13px;min-height:0;padding:10px 0}.appearance-sample :deep(.text-line){padding:0 10px;gap:8px}:where(.appearance-sample) :deep(.syntax-token){color:var(--syntax-light);font-style:var(--syntax-l-italic);font-weight:var(--syntax-l-weight);text-decoration:var(--syntax-l-line)}:where(.appearance-sample[data-code-mode="dark"]) :deep(.syntax-token){color:var(--syntax-dark);font-style:var(--syntax-d-italic);font-weight:var(--syntax-d-weight);text-decoration:var(--syntax-d-line)}:where(.appearance-sample[data-code-mode="dark"]) :deep(.text-code){color:#e8ecf2;background:#242a32}:where(.appearance-sample[data-code-mode="light"]) :deep(.text-code){color:#20262e;background:#ffffff}
.appearance-css summary{cursor:pointer;font-weight:600;padding:4px 0}.appearance-css-actions{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin:6px 0}.appearance-css-actions button{font-size:12px}.appearance-css textarea{width:100%;height:160px;resize:vertical;min-height:80px;max-height:300px;box-sizing:border-box;padding:8px;border:1px solid var(--line);border-radius:4px;color:var(--text);background:var(--well);font:12px/1.6 Consolas,monospace;white-space:pre}.appearance-css-help{margin:6px 0;overflow-wrap:anywhere}.appearance-error{color:#c0392b;line-height:1.5;margin:8px 0 0}
.code-appearance-dialog>footer{flex-shrink:0;padding:12px 16px;border-top:1px solid var(--line);display:flex;gap:12px;align-items:center;justify-content:space-between}.appearance-status{font-size:12px;color:var(--muted);line-height:1.5}.appearance-actions{display:flex;gap:8px;flex-shrink:0}.appearance-actions .appearance-save{background:var(--accent);color:#fff;border-color:var(--accent)}
@media(max-width:760px){.appearance-body{display:flex;flex-direction:column;gap:12px}.appearance-preview-column{display:contents}.appearance-caption{order:0}.appearance-sample{order:1;max-height:180px;flex-shrink:0;margin-bottom:0}.appearance-controls{order:2}.appearance-css{order:3}.appearance-error{order:4}.code-appearance-dialog>footer{align-items:stretch;flex-direction:column}.appearance-actions{justify-content:flex-end}.appearance-color-row{grid-template-columns:85px 30px minmax(62px,1fr) 77px 28px}}
</style>
